import{_ as a,o as t,c as i,ak as o}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Game design PDF editions","description":"Two editions prepared October 22, 2026 follow the supplied GDD formats. Both use the current explorable 3D gameplay with Quiz, Wordle and BlockMatch, offline SQLite saves and ","frontmatter":{"title":"Game design PDF editions","description":"Two editions prepared October 22, 2026 follow the supplied GDD formats. Both use the current explorable 3D gameplay with Quiz, Wordle and BlockMatch, offline SQLite saves and ","source":"docs/gdd-template-editions.md","category":"Other documents","sourceUpdated":"2026-10-22T18:47:06+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/gdd-template-editions.md","filePath":"content/docs/gdd-template-editions.md"}'),r={name:"content/docs/gdd-template-editions.md"};function n(s,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<div><h1 id="game-design-pdf-editions">Game design PDF editions<a class="header-anchor" href="#game-design-pdf-editions" aria-label="Link to this section">​</a></h1><p>Two editions prepared October 22, 2026 follow the supplied GDD formats. Both use the current explorable 3D gameplay with Quiz, Wordle and BlockMatch, offline SQLite saves and the approved audience aged 12-17. Exact mini-game rules remain open design decisions. These replace neither the baseline nor the team&#39;s rule approvals.</p><p>Read both directly in the website&#39;s <strong>GDD PDFs</strong> viewer. No download is required in browsers with PDF display support.</p><h2 id="illustrated-example-format">Illustrated example format<a class="header-anchor" href="#illustrated-example-format" aria-label="Link to this section">​</a></h2><p><a href="/Chainy-Docs/attachments/output/pdf/Chainy-GDD-Example-Format.pdf">Open the illustrated example edition</a></p><p>Follows the sample&#39;s cover, contents, numbered brief, gameplay, world, art, mechanics, characters, plan and references. Includes current-gameplay diagrams and clearly labeled art references.</p><h2 id="structured-template-format">Structured template format<a class="header-anchor" href="#structured-template-format" aria-label="Link to this section">​</a></h2><p><a href="/Chainy-Docs/attachments/output/pdf/Chainy-GDD-Template-Format.pdf">Open the structured template edition</a></p><p>Follows the six-page template&#39;s field order: overview and technical specifications; gameplay and outline; design guidelines and definitions; referenced flowchart; player definitions, properties and rewards; and UI.</p><h2 id="source-and-review-boundary">Source and review boundary<a class="header-anchor" href="#source-and-review-boundary" aria-label="Link to this section">​</a></h2><p>The two supplied PDF files control presentation only. Current facts come from the <a href="/Chainy-Docs/content/docs/project-baseline.html">baseline</a>, <a href="/Chainy-Docs/content/docs/game-design.html">game design</a> and <a href="/Chainy-Docs/content/docs/archive/source-material/technical-design-christian-2026-10-12.html">Christian&#39;s adopted design</a>. The earlier October 8 illustrated PDF remains historical and contains superseded mechanics.</p><p>November 3-6 beta and November 21, 2026 pre-final remain fixed. Documents and diagrams do not establish build readiness or school completion percentages. PDF production checks cover page layout, required fields and consistency with the current design; they do not validate game implementation.</p></div>',1)])])}const u=a(r,[["render",n]]);export{m as __pageData,u as default};
